function pieceSvgMarkup(pieceCode){
  if(!pieceCode) return "";
  const key=(pieceCode===pieceCode.toUpperCase()?"w":"b")+pieceCode.toUpperCase();
  const src=CHESS_PIECE_IMAGES[key];
  return src ? '<img class="chess-piece-img" src="'+src+'" alt="" draggable="false">' : (CHESS_PIECE_SVG[key]||"");
}
