function editorRefresh(){
 const panel=document.getElementById('editorPanel');if(!panel)return;
 panel.style.display=(editorMode && vqcCurrentSection==='editor')?'block':'none';
 const playBar=document.getElementById('editorPlayBar');if(playBar)playBar.style.display=(editorPlaying && vqcCurrentSection==='editor')?'flex':'none';
 const pal=document.getElementById('editorPalette');pal.innerHTML='';
 ['K','Q','R','B','N','P','k','q','r','b','n','p',''].forEach(code=>{
  const b=document.createElement('button');b.type='button';b.draggable=true;b.className='editor-piece'+(editorPiece===code?' active':'');
  b.title=code?('Đặt quân '+code):'Xóa quân ở ô';b.setAttribute('aria-label',b.title);
  b.innerHTML=code?pieceSvgMarkup(code):`<span class="editor-eraser-content"><svg viewBox="0 0 48 48" width="32" height="32" fill="none" aria-hidden="true"><path d="M13 30 28 11a5 5 0 0 1 7 0l7 7a5 5 0 0 1 0 7L27 42H16L7 34a5 5 0 0 1 0-7l6-7" fill="#f4a9b8" stroke="#9c4664" stroke-width="2.2" stroke-linejoin="round"/><path d="m18 24 15 14" stroke="#9c4664" stroke-width="2.2"/><path d="M27 42h16" stroke="#64748b" stroke-width="2.5" stroke-linecap="round"/></svg></span>`;if(!code)b.classList.add('editor-eraser');
  b.onclick=()=>{editorPiece=code;editorFrom=null;editorRefresh();};b.ondragstart=e=>{editorPiece=code;editorFrom=null;if(e.dataTransfer){e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('application/x-chess-editor',code||'erase');e.dataTransfer.setData('text/plain','palette:'+ (code||'erase'));}};pal.appendChild(b);
 });
}
function editorPut(i){
 if(!editorMode)return;
 if(roomRef&&role!=="teacher"){vqcAlert("Chỉ giáo viên được chỉnh sửa thế cờ trong phòng.");return;}
 history.push([...state]);
 state[i]=editorPiece; selected=lastFrom=lastTo=null;
 renderBoard();editorPublish();
}
function editorFlip(){editorFlipped=!editorFlipped;renderBoard();}
function editorFen(){
 let out=[];for(let r=0;r<8;r++){let row='',empty=0;for(let c=0;c<8;c++){let v=state[r*8+c];if(!v){empty++;continue;}if(empty){row+=empty;empty=0;}row+=v;}if(empty)row+=empty;out.push(row);}
 return out.join('/')+' '+(document.getElementById('editorTurn')?.value||'w')+' - - 0 1';
}
function editorCopyFen(){const fen=editorFen();if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(fen).then(()=>vqcAlert('Đã sao chép FEN: '+fen)).catch(()=>prompt('Sao chép FEN:',fen));}else prompt('Sao chép FEN:',fen);}
function editorLoadFen(){
 const raw=prompt('Nhập FEN của thế cờ:');if(raw===null)return;
 const rows=raw.trim().split(/\s+/)[0].split('/');let next=[];
 if(rows.length!==8){vqcAlert('FEN không hợp lệ: cần 8 hàng.');return;}
 for(const row of rows){let count=0;for(const ch of row){if(/[1-8]/.test(ch)){let n=Number(ch);count+=n;for(let j=0;j<n;j++)next.push('');}else if(/[KQRBNPkqrbnp]/.test(ch)){next.push(ch);count++;}else{vqcAlert('FEN chứa ký tự không hợp lệ.');return;}}if(count!==8){vqcAlert('Mỗi hàng FEN phải có 8 ô.');return;}}
 history.push([...state]);state=next;const turn=raw.trim().split(/\s+/)[1];if(turn==='w'||turn==='b')document.getElementById('editorTurn').value=turn;renderBoard();editorPublish();
}
async function editorPublish(){
 if(!roomRef||role!=="teacher"||editorPlaying)return;
 try{await roomRef.update({state:[...state],editorSession:{mode:'edit',fen:editorFen()},pieceGame:null,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});}
 catch(e){console.warn('Không đồng bộ được thế cờ',e);document.getElementById('status').textContent='⚠️ Không đồng bộ được thế cờ. Kiểm tra Firestore Rules.';}
}
function editorSetStatus(){
 const el=document.getElementById('editorPlayStatus');if(!el||!editorChess)return;
 let msg=editorChess.turn()==='w'?'Trắng đi':'Đen đi';
 if(editorChess.in_checkmate())msg='Chiếu hết!';else if(editorChess.in_draw())msg='Ván cờ hòa';else if(editorChess.in_check())msg+=' — đang bị chiếu';
 el.textContent='♟ Luyện thế cờ: '+msg;
}
async function editorStartHere(){
 if(roomRef&&role!=="teacher"){vqcAlert('Giáo viên là người bắt đầu thế cờ trong phòng.');return;}
 if(typeof Chess!=='function'){vqcAlert('Chưa tải được thư viện luật cờ. Kiểm tra kết nối Internet.');return;}
 const fen=editorFen();let game;
 const kingsW=state.filter(x=>x==='K').length,kingsB=state.filter(x=>x==='k').length;
 if(kingsW!==1||kingsB!==1){vqcAlert('Cần đúng 1 Vua trắng và 1 Vua đen.');return;}
 if(state.some((p,i)=>(p==='P'||p==='p')&&(i<8||i>=56))){vqcAlert('Tốt không thể đứng ở hàng 1 hoặc hàng 8.');return;}
 const wk=state.indexOf('K'),bk=state.indexOf('k');
 if(Math.abs(Math.floor(wk/8)-Math.floor(bk/8))<=1&&Math.abs(wk%8-bk%8)<=1){vqcAlert('Hai Vua không được đứng cạnh nhau.');return;}
 try{game=new Chess();if(!game.load(fen))throw Error('FEN không hợp lệ');
 const opposite=game.turn()==='w'?'b':'w';
 // Không cho bắt đầu nếu Vua của bên không đến lượt đang bị chiếu.
 const swapped=fen.replace(/ (w|b) /,(_,c)=>' '+(c==='w'?'b':'w')+' ');
 const checkOther=new Chess();if(checkOther.load(swapped)&&checkOther.in_check())throw Error('Vua bên không đến lượt đang bị chiếu');
 }
 catch(e){vqcAlert('Thế cờ chưa hợp lệ để bắt đầu. Cần có đúng một Vua trắng, một Vua đen, các quân ở vị trí hợp lệ và chọn đúng lượt đi.');return;}
 editorChess=game;editorPlaying=true;editorMode=false;pieceGame=null;selected=null;history=[];
 editorRefresh();editorSetStatus();renderBoard();
 if(roomRef){try{await roomRef.update({state:[...state],editorSession:{mode:'play',fen:game.fen()},pieceGame:null,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});}
 catch(e){vqcAlert('Chưa thể bắt đầu cùng học sinh: Firestore từ chối ghi. Kiểm tra Security Rules.');}}
}
async function editorBackToEdit(){
 if(roomRef&&role!=="teacher"){vqcAlert('Chỉ giáo viên được chuyển về chế độ chỉnh sửa.');return;}
 editorPlaying=false;editorMode=true;editorChess=null;selected=null;editorRefresh();renderBoard();await editorPublish();
}
async function editorPlayMove(from,to,promotion){
 if(!editorChess)return;
 const sq=i=>String.fromCharCode(97+i%8)+(8-Math.floor(i/8));
 const piece=editorChess.get(sq(from));if(!piece)return;
 const legal=editorChess.moves({square:sq(from),verbose:true}).filter(m=>m.to===sq(to));
 if(promotion===undefined&&legal.some(m=>m.promotion)){editorShowPromotion(from,to,piece.color);return;}
 let move=editorChess.move({from:sq(from),to:sq(to),promotion:promotion||'q'});
 if(!move){document.getElementById('status').textContent='⚠️ Nước đi không hợp lệ hoặc chưa đúng lượt.';selected=null;renderBoard();return;}
 state=editorChess.board().flat().map(x=>x?(x.color==='w'?x.type.toUpperCase():x.type):'');
 selected=null;lastFrom=from;lastTo=to;editorSetStatus();renderBoard();
 if(move.promotion)vqcNotify('Đã phong cấp thành '+({q:'Hậu',r:'Xe',b:'Tượng',n:'Mã'}[move.promotion]),'success');
 if(roomRef){try{await roomRef.update({state:[...state],lastFrom:from,lastTo:to,editorSession:{mode:'play',fen:editorChess.fen()},lastActor:role,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});}
 catch(e){document.getElementById('status').textContent='⚠️ Không đồng bộ được nước đi. Kiểm tra Firestore Rules.';}}
}

function vqcNotify(message,type='info'){
 const wrap=document.getElementById('vqcToasts');if(!wrap)return;
 const item=document.createElement('div');item.className='vqc-toast '+type;item.setAttribute('role','status');
 const icon=type==='error'?'⚠️':type==='success'?'✅':'♟️';item.textContent=icon+' '+String(message);
 wrap.appendChild(item);setTimeout(()=>item.remove(),5200);
}
function vqcAlert(message){vqcNotify(message,/không|lỗi|chưa|cần|sai|từ chối|hợp lệ/i.test(message)?'error':'info');}
let editorPendingPromotion=null;
function editorClosePromotion(){document.getElementById('editorPromotionDialog').classList.remove('open');editorPendingPromotion=null;}
function editorShowPromotion(from,to,color){
 editorPendingPromotion={from,to};const area=document.getElementById('editorPromotionChoices');area.replaceChildren();
 [['q','Hậu'],['r','Xe'],['b','Tượng'],['n','Mã']].forEach(([type,label])=>{
  const btn=document.createElement('button');btn.type='button';
  const img=document.createElement('img');img.src=CHESS_PIECE_IMAGES[color+type.toUpperCase()];img.alt=label;
  const txt=document.createElement('span');txt.textContent=label;btn.append(img,txt);
  btn.onclick=()=>{const pending=editorPendingPromotion;editorClosePromotion();if(pending)editorPlayMove(pending.from,pending.to,type);};area.appendChild(btn);
 });document.getElementById('editorPromotionDialog').classList.add('open');
}

