function getStartPosition(){



    const s =

        Array(64).fill("");



    const blackBack =

        "rnbqkbnr";



    const whiteBack =

        "RNBQKBNR";





    /* Quân đen */



    blackBack

        .split("")

        .forEach(

            (piece,index) =>

            s[index] = piece

        );





    for(

        let i = 8;

        i < 16;

        i++

    ){



        s[i] = "p";



    }





    /* Quân trắng */



    for(

        let i = 48;

        i < 56;

        i++

    ){



        s[i] = "P";



    }





    whiteBack

        .split("")

        .forEach(

            (piece,index) =>

            s[56 + index] = piece

        );





    return s;



}





