const board =

    document.getElementById("board");





function getPieceGameLegalMoves(from){
    if(!pieceGame || from===null || !state[from]) return [];
    const moving=state[from].toUpperCase();
    if(moving!==pieceGame.piece) return [];
    const moves=[];
    for(let to=0;to<64;to++){
        if(isLegalPieceGameMove(from,to,pieceGame.piece)) moves.push(to);
    }
    return moves;
}

function renderBoard(){
    if(lastFrom!==null&&lastTo!==null&&Number.isInteger(lastFrom)&&Number.isInteger(lastTo))
      window.vqcLastMove?.mark('board',squareName(lastFrom),squareName(lastTo));
    else window.vqcLastMove?.clear('board');
    const center=document.querySelector('section.center');
    if(center)center.classList.toggle('vqc-practice-active',!!pieceGame);

    if(editorMode)editorRefresh();



    board.innerHTML = "";
    board.classList.toggle("editor-flipped",editorFlipped && (editorMode || editorPlaying));





    ((editorMode || editorPlaying) && editorFlipped ? [...state].reverse() : state).forEach(

        (piece,displayIndex) => {
            const index = (editorMode || editorPlaying) && editorFlipped ? 63-displayIndex : displayIndex;



            const row =

                Math.floor(displayIndex / 8);



            const col =

                displayIndex % 8;





            const square =

                document.createElement("div");





            square.className =

                "square " +

                (

                    (row + col) % 2 === 0

                    ? "light"

                    : "dark"

                );





            /* Ô đang chọn */



            if(

                selected === index

            ){



                square.classList.add(

                    "selected"

                );



            }





            /* Nước đi vừa rồi */



            if(

                index === lastFrom ||

                index === lastTo

            ){



                square.classList.add(

                    "last"

                );



            }





            square.dataset.index =

                index;





            /* Cho phép thả quân */



            square.ondragover =

                event => {



                    event.preventDefault();



                };





            square.ondrop =

                event => {



                    event.preventDefault();



                    if(editorMode){
                        if(roomRef&&role!=="teacher"){document.getElementById('status').textContent='Chỉ giáo viên chỉnh sửa thế cờ trong phòng.';return;}
                        const payload=event.dataTransfer?.getData('text/plain')||'';
                        if(payload.startsWith('palette:')){
                            const code=payload.slice(8);history.push([...state]);state[index]=code==='erase'?'':code;
                        }else if(editorFrom!==null&&editorFrom!==index){
                            history.push([...state]);state[index]=state[editorFrom];state[editorFrom]='';
                        }else{return;}
                        editorFrom=null;renderBoard();editorPublish();return;
                    }
                    if(editorPlaying){
                        const raw=event.dataTransfer?.getData('text/plain');
                        const from=raw!==undefined&&/^\d+$/.test(raw)?Number(raw):selected;
                        if(Number.isInteger(from)&&from>=0&&from<64)editorPlayMove(from,index);
                        return;
                    }
                    movePiece(index);



                };





            /* Click */



            square.onclick =

                () => {



                    clickSquare(index);



                };





            /* Chấm gợi ý và vòng tròn ăn quân ở mọi chế độ chơi trên bàn chính. */
            const boardHints = editorPlaying && editorChess && selected !== null
                ? editorChess.moves({square:'abcdefgh'[selected%8]+(8-Math.floor(selected/8)),verbose:true}).map(m=>({to:(8-Number(m.to[1]))*8+'abcdefgh'.indexOf(m.to[0]),capture:!!m.captured||m.flags.includes('e')}))
                : pieceGame && selected !== null
                ? getPieceGameLegalMoves(selected).map(to=>({to,capture:!!state[to]}))
                : [];
            const boardHint=boardHints.find(m=>m.to===index);
            if(boardHint){
                const hint=document.createElement('span');
                hint.className=boardHint.capture?'capture-hint':'move-hint';
                hint.setAttribute('aria-hidden','true');square.appendChild(hint);
            }
            if(displayIndex%8===0){const rank=document.createElement('span');rank.className='editor-coordinate editor-rank';rank.textContent=String(8-Math.floor(index/8));square.appendChild(rank);}
            if(displayIndex>=56){const file=document.createElement('span');file.className='editor-coordinate editor-file';file.textContent='abcdefgh'[index%8];square.appendChild(file);}

            /* Hiển thị ngôi sao cần nhặt trong thử thách */
            if(pieceGame && pieceGame.stars && pieceGame.stars.has(index)){
                square.classList.add("has-star");
                const starElement = document.createElement("span");
                starElement.className = "board-star";
                starElement.innerHTML = `<svg class="vqc-star-svg" viewBox="0 0 100 100" aria-hidden="true" focusable="false"><defs><linearGradient id="vqcStarGold" x1="0" y1="0" x2="0.85" y2="1"><stop offset="0" stop-color="#fff6a0"/><stop offset=".36" stop-color="#ffe365"/><stop offset=".72" stop-color="#ffbe29"/><stop offset="1" stop-color="#ed9514"/></linearGradient><filter id="vqcStarShadow" x="-40%" y="-40%" width="180%" height="190%"><feGaussianBlur in="SourceAlpha" stdDeviation="2.3"/><feOffset dy="2"/><feComponentTransfer><feFuncA type="linear" slope=".28"/></feComponentTransfer><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><path d="M50 9 L62.6 35.4 L91.5 39.2 L70.5 59.7 L75.7 88.5 L50 74.6 L24.3 88.5 L29.5 59.7 L8.5 39.2 L37.4 35.4 Z" fill="url(#vqcStarGold)" stroke="#e5a128" stroke-width="2.7" stroke-linejoin="round" filter="url(#vqcStarShadow)"/><path d="M50 17 L60.4 39 L84 42 L66.7 59 L71 81" fill="none" stroke="#fff9cb" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" opacity=".7"/><ellipse cx="39" cy="43" rx="6" ry="3" transform="rotate(-28 39 43)" fill="#fffbe4" opacity=".85"/></svg>`;
                starElement.setAttribute("aria-label", "Ngôi sao");
                square.appendChild(starElement);
            }



            /* Nếu ô có quân */



            if(piece){



                const pieceElement =

                    document.createElement(

                        "span"

                    );





                pieceElement.className =

                    "piece";





                pieceElement.innerHTML = pieceSvgMarkup(piece);





                pieceElement.draggable =

                    true;





                pieceElement.ondragstart =

                    event => {

                        if(editorMode){editorFrom=index;}else{selected = index;}

                        // Giữ kích thước ô cờ cố định khi kéo quân.
                        // Chỉ truyền dữ liệu kéo, không thay đổi layout của bàn cờ.
                        if(event.dataTransfer){
                            event.dataTransfer.effectAllowed = "move";
                            event.dataTransfer.setData("text/plain", String(index));
                        }

                    };





                square.appendChild(

                    pieceElement

                );



            }





            board.appendChild(

                square

            );



        }

    );



}





/* =========================================================

   5. CLICK VÀO Ô

========================================================= */



function clickSquare(index){
    // Không cho phép đi tự do ngoài các bài học có luật.
    if(!pieceGame && !editorMode && !editorPlaying)return;

    if(editorMode){editorPut(index);return;}
    if(editorPlaying){
      if(selected===null){if(state[index] && editorChess && editorChess.get('abcdefgh'[index%8]+(8-Math.floor(index/8)))?.color===editorChess.turn()){selected=index;renderBoard();}return;}
      if(selected===index){selected=null;renderBoard();return;}
      if(state[index] && editorChess && editorChess.get('abcdefgh'[index%8]+(8-Math.floor(index/8)))?.color===editorChess.turn()){selected=index;renderBoard();return;}
      editorPlayMove(selected,index);return;
    }
    



    /* Chưa chọn quân */



    if(selected === null){



        if(state[index]){



            selected = index;



            renderBoard();



        }



        return;



    }





    /* Click lại chính ô đó */



    if(selected === index){



        selected = null;



        renderBoard();



        return;



    }





    movePiece(index);



}





/* =========================================================

   6. DI CHUYỂN QUÂN

========================================================= */



function movePiece(to){
    



    if(selected === null){

        return;

    }





    const from =

        selected;





    if(!state[from]){



        selected = null;



        renderBoard();



        return;



    }





    /* Trong trò chơi quân cờ: chỉ cho phép nước đi đúng luật */
    if(pieceGame){
        if(!isLegalPieceGameMove(from,to,pieceGame.piece)){
            document.getElementById("status").textContent = "💡 Chưa đúng luật của " + pieceGameNames[pieceGame.piece] + ". Thử lại nhé!";
            const bad = board.children[to];
            if(bad){ bad.classList.remove("illegal"); void bad.offsetWidth; bad.classList.add("illegal"); }
            selected = from;
            return;
        }
    }

    /* Lưu để hoàn tác */



    history.push(

        [...state]

    );





    const movingPiece =

        state[from];





    state[to] =

        movingPiece;





    state[from] =

        "";

    if(pieceGame){
        pieceGame.hasMoved = true;
        if(pieceGame.stars.has(to)){
            pieceGame.stars.delete(to);
            pieceGame.score++;
            accountSaveProgress("basic_"+pieceGame.piece,pieceGame.score>=6,pieceGame.score);
            updatePieceGameBar();
            if(pieceGame.score >= 6){
                // Cả giáo viên và học sinh nhận phần thưởng qua cùng trạng thái phòng.
                rewardDismissedInRoom=false;
                showStarReward(pieceGame.piece);
                if(typeof window.vqcAdventurePieceCompleted==='function')window.vqcAdventurePieceCompleted(pieceGame.piece);
                document.getElementById("status").innerHTML = "🏆 <b>Xuất sắc!</b> Em đã nhặt đủ 6/6 ngôi sao với " + pieceGameNames[pieceGame.piece] + "!";
            }
        }
    }



    selected =

        null;





    lastFrom =

        from;





    lastTo =

        to;





    const message =

        (

            role === "student"

            ? "Học sinh"

            : "Giáo viên"

        )

        +

        " đi "

        +

        squareName(from)

        +

        " → "

        +

        squareName(to);





    addLog(message);





    if(!pieceGame || pieceGame.score < 6){
        document.getElementById(
            "status"
        ).innerHTML = pieceGame
            ? "⭐ Đúng luật! Điểm: <b>" + pieceGame.score + "/6</b>"
            : "👏 <b>Tốt lắm!</b> " + squareName(from) + " → " + squareName(to);
    }





    // Nhặt sao tức thì: không phóng to, bay lên hay chờ hoạt ảnh.
    renderBoard();

    sendBoard();



}





/* =========================================================

   7. TÊN Ô CỜ

========================================================= */



function squareName(index){



    const files =

        "abcdefgh";





    const column =

        index % 8;





    const row =

        Math.floor(index / 8);





    return (

        files[column]

        +

        (8 - row)

    );



}





/* =========================================================

   8. NHẬT KÝ

========================================================= */



function addLog(text){



    const log =

        document.getElementById(

            "log"

        );





    const entry =

        document.createElement(

            "div"

        );





    entry.className =

        "log-entry";





    entry.textContent =

        new Date()

            .toLocaleTimeString(

                "vi-VN"

            )

        +

        " • "

        +

        text;





    log.prepend(

        entry

    );



}





