// Mười thế cờ từ Hình 52–61, Trắng đi trước. Chess.js kiểm tra nước đi hợp lệ.
const MATE_EXERCISES = [{"num": 52, "fen": "7R/8/8/8/3p4/8/r7/k1K4Q w - - 0 1"}, {"num": 53, "fen": "8/2p5/2P5/2K5/kp6/1p6/PP6/Q7 w - - 0 1"}, {"num": 54, "fen": "7k/5K2/6p1/6Pb/8/7B/7R/8 w - - 0 1"}, {"num": 55, "fen": "5K1k/7p/7R/8/2R5/1p6/b7/8 w - - 0 1"}, {"num": 56, "fen": "2kr4/K1pp4/8/8/8/8/7Q/3R4 w - - 0 1"}, {"num": 57, "fen": "8/8/6k1/7R/5K2/5Q2/8/8 w - - 0 1"}, {"num": 58, "fen": "8/rp6/k7/8/8/1R1K3Q/8/8 w - - 0 1"}, {"num": 59, "fen": "8/8/8/pp6/kB5Q/8/K2b4/8 w - - 0 1"}, {"num": 60, "fen": "6k1/7p/7K/8/8/8/8/B4Q2 w - - 0 1"}, {"num": 61, "fen": "6r1/1R6/8/p5r1/kp6/7R/1P5P/7K w - - 0 1"}];
// CHỈ dùng 10 biến chính do người dùng cung cấp, không có biến phụ “Nếu…”.
// Định dạng UCI: Trắng đi đầu, Đen đáp, Trắng chiếu hết.
const MATE_BOOK = [
 {first:'h8a8',reply:'a2a8',finish:'h1a8'}, // 52: Ra8+ Rxa8 Qa8#
 {first:'a2a3',reply:'b4a3',finish:'a1a3'}, // 53: a3 bxa3 Qa3#
 {first:'h3f5',reply:'h8h7',finish:'h2h5'}, // 54: Bf5 Kh7 Rxh5#
 {first:'h6g6',reply:'h7g6',finish:'c4h4'}, // 55: Rg6 hxg6 Rh4#
 {first:'h2d6',reply:'c7d6',finish:'d1c1'}, // 56: Qd6 cxd6 Rc1#
 {first:'f3b7',reply:'g6h5',finish:'b7h7'}, // 57: Qb7 Kxh5 Qh7#
 {first:'h3d7',reply:'a6a5',finish:'d7b5'}, // 58: Qd7 Ka5 Qb5#
 {first:'h4d8',reply:'a4b4',finish:'d8d4'}, // 59: Qd8 Kxb4 Qd4#
 {first:'a1h8',reply:'g8h8',finish:'f1f8'}, // 60: Bh8 Kxh8 Qf8#
 {first:'h3a3',reply:'b4a3',finish:'b2b3'}  // 61: Ra3+ bxa3 b3#
];
function mateBookMove(move){return !!(move&&MATE_BOOK[mateIndex]&&move.from+move.to===MATE_BOOK[mateIndex].first);}
function mateChangeVariation(){/* Không dùng biến phụ. */}
let mateChess=null,mateIndex=0,mateSelected=null,mateWhiteMoves=0,mateBusy=false,mateDone=false;
function mateMessage(t){document.getElementById('mateMessage').textContent=t;}
function mateCoords(i){return 'abcdefgh'[i%8]+(8-Math.floor(i/8));}
function openMateExercises(i){
  document.getElementById("vqcHomeHero")?.setAttribute("hidden", "");
  if(typeof Chess==='undefined'){vqcAlert('Cần có Internet để tải thư viện luật cờ vua. Hãy thử tải lại trang.');return;}
  document.getElementById('mateOverlay').classList.add('open');
  mateIndex=(i+MATE_EXERCISES.length)%MATE_EXERCISES.length;
  mateReset();
}
function closeMateExercises(){document.getElementById('mateOverlay').classList.remove('open');}
function matePrev(){openMateExercises(mateIndex-1);}
function mateNext(){openMateExercises(mateIndex+1);}
function mateReset(){
 const p=MATE_EXERCISES[mateIndex];mateChess=new Chess(p.fen);mateSelected=null;mateWhiteMoves=0;mateBusy=false;mateDone=false;
 document.getElementById('mateTitle').textContent='♔ Chiếu hết trong 2 nước — Bài '+(mateIndex+1)+'/10 (Hình '+p.num+')';
 
 mateMessage('Trắng đi trước. Hãy tìm nước đầu tiên của biến chính.');renderMateBoard();
}
function renderMateBoard(){
  if(!mateChess)return;
  window.vqcLastMove?.fromChess('mateBoard',mateChess);
  const el=document.getElementById('mateBoard');el.innerHTML='';
  const hints=mateSelected?mateChess.moves({square:mateSelected,verbose:true}).map(x=>x.to):[];
  for(let i=0;i<64;i++){
    const sq=mateCoords(i),pc=mateChess.get(sq),cell=document.createElement('div');
    cell.dataset.square=sq;
    cell.className='mate-square '+((Math.floor(i/8)+i%8)%2?'dark':'light');
    if(sq===mateSelected)cell.classList.add('selected');
    if(hints.includes(sq))cell.classList.add('hint');
    if(pc){const wrap=document.createElement('span');wrap.className='piece';wrap.innerHTML=pieceSvgMarkup(pc.color==='w'?pc.type.toUpperCase():pc.type);cell.appendChild(wrap);}
    cell.onclick=()=>mateClick(sq);el.appendChild(cell);
  }
}
function mateClick(sq){
 if(!mateChess||mateBusy||mateDone||mateChess.turn()!=='w')return;
 const pc=mateChess.get(sq);
 if(!mateSelected){if(pc&&pc.color==='w'){mateSelected=sq;renderMateBoard();}return;}
 if(pc&&pc.color==='w'){mateSelected=sq;renderMateBoard();return;}
 const from=mateSelected, attempted=from+sq,book=MATE_BOOK[mateIndex];
 mateSelected=null;
 const expected=mateWhiteMoves===0?book.first:book.finish;
 if(attempted!==expected){mateMessage('Nước đi chưa đúng biến chính. Hãy thử lại.');renderMateBoard();return;}
 const mv=mateChess.move({from,to:sq,promotion:'q'});
 if(!mv){mateMessage('⚠️ Nước đi trong đáp án không hợp lệ với vị trí quân hiện tại. Cần đối chiếu lại thế cờ.');renderMateBoard();return;}
 mateWhiteMoves++;renderMateBoard();syncMateExercise();
 if(mateWhiteMoves===2){
  mateDone=true;
  mateMessage(mateChess.in_checkmate()?'🏆 Chính xác! Chiếu hết theo biến chính!':'⚠️ Đã đi hết biến chính, nhưng vị trí hiện tại chưa được xác nhận là chiếu hết. Cần kiểm tra lại thế cờ.');
  if(mateChess.in_checkmate())accountSaveProgress('mate2_'+MATE_EXERCISES[mateIndex].num,true,1);
  syncMateExercise();return;
 }
 const black=mateChess.move({from:book.reply.slice(0,2),to:book.reply.slice(2,4),promotion:'q'});
 if(!black){mateDone=true;mateMessage('⚠️ Nước đáp trả của Đen trong biến chính không hợp lệ với thế cờ hiện tại.');syncMateExercise();return;}
 
 mateMessage('Đen đi '+black.san+'. Đến lượt Trắng tìm nước chiếu hết.');renderMateBoard();syncMateExercise();
}
function mateHint(){
 if(!mateChess||mateDone)return;
 const book=MATE_BOOK[mateIndex],move=mateWhiteMoves===0?book.first:book.finish;
 mateMessage('💡 Gợi ý: Chọn quân ở ô '+move.slice(0,2)+' và di chuyển đến '+move.slice(2,4)+'.');
}
async function syncMateExercise(){
  if(!roomRef||!mateChess)return;
  try{await roomRef.update({mateExercise:{index:mateIndex,fen:mateChess.fen(),whiteMoves:mateWhiteMoves,done:mateDone,actor:role},updatedAt:firebase.firestore.FieldValue.serverTimestamp()});}catch(e){console.warn('Chưa đồng bộ bài tập',e);}
}
function receiveMateExercise(data){
  if(!data||typeof Chess==='undefined')return;
  if(!Number.isInteger(data.index)||data.index<0||data.index>=10||typeof data.fen!=='string')return;
  if(!mateChess||mateIndex!==data.index||mateChess.fen()!==data.fen){
    mateIndex=data.index;mateChess=new Chess(data.fen);mateWhiteMoves=data.whiteMoves||0;mateDone=!!data.done;mateSelected=null;
    document.getElementById('mateOverlay').classList.add('open');
    document.getElementById('mateTitle').textContent='♔ Chiếu hết trong 2 nước — Hình '+MATE_EXERCISES[mateIndex].num;
    renderMateBoard();mateMessage(mateDone?'Đã hoàn thành hoặc kết thúc lượt.':'Bàn cờ đang được đồng bộ từ thiết bị còn lại.');
  }
}


