// Hình 164: giải thế cờ bằng luật thay vì khóa một biến đáp án in trong sách.
const mate164Memo=new Map();
function mate164CanForce(game,remaining){
 if(game.in_checkmate())return game.turn()==='b';
 if(remaining<=0||game.in_draw()||game.in_stalemate())return false;
 const key=game.fen().split(' ').slice(0,4).join(' ')+'|'+remaining;
 if(mate164Memo.has(key))return mate164Memo.get(key);
 const moves=game.moves({verbose:true});
 let result=game.turn()==='w'?false:true;
 for(const move of moves){
  game.move(move);
  const possible=mate164CanForce(game,remaining-(move.color==='w'?1:0));
  game.undo();
  if(game.turn()==='w'&&possible){result=true;break;}
  if(game.turn()==='b'&&!possible){result=false;break;}
 }
 mate164Memo.set(key,result);
 return result;
}
function applyMate164Move(from,to,promotion){
 const move=mate3Chess.moves({verbose:true}).find(m=>m.from===from&&m.to===to&&(!m.promotion||m.promotion===promotion));
 if(!move){mate3Message('Nước đi không hợp lệ.');renderMate3();return;}
 mate3Chess.move(move);
 const remaining=3-(mate3White+1);
 if(!mate3Chess.in_checkmate()&&!mate164CanForce(mate3Chess,remaining)){
  mate3Chess.undo();mate3Message('Nước đi này chưa bảo đảm chiếu hết trong 3 nước. Em hãy thử cách khác!');renderMate3();return;
 }
 mate3History.push(mate3Key(move));mate3White++;
 if(mate3Chess.in_checkmate()){
  mate3Done=true;renderMate3();mate3Message('🏆 Chính xác! Em đã chiếu hết Vua Đen!');
  accountSaveProgress('mate3_164',true,1);return;
 }
 const replies=mate3Chess.moves({verbose:true});
 // Chọn một cách phòng thủ hợp lệ; ưu tiên nước buộc Trắng phải suy nghĩ tiếp.
 const reply=replies[0];
 if(!reply){mate3Done=true;renderMate3();mate3Message('Ván cờ đã kết thúc.');return;}
 mate3Chess.move(reply);mate3History.push(mate3Key(reply));
 renderMate3();mate3Message('Đen đã đi một nước hợp lệ. Em hãy tìm nước tiếp theo!');
}
function applyMate3Move(from,to,promotion){
 if(MATE3_DATA[mate3Index].num===164){applyMate164Move(from,to,promotion);return;}
 const moves=mate3Chess.moves({verbose:true}).filter(m=>m.from===from&&m.to===to&&(!m.promotion||m.promotion===promotion));
 if(!moves.length){mate3Message('Nước đi không hợp lệ.');renderMate3();return;}
 const book=mate3Options().map(l=>l[mate3History.length]);
 const selected=moves[0];
 if(!book.includes(mate3Key(selected))){
  mate3Message(promotion?'Em đã chọn phong cấp thành '+({q:'Hậu',r:'Xe',n:'Mã',b:'Tượng'}[promotion])+'. Đây chưa phải đáp án của bài. Hãy thử quân khác.':'Nước này chưa đúng phương án trong sách. Hãy thử lại hoặc chọn Gợi ý.');
  renderMate3();return;
 }
 mate3Chess.move(selected);mate3History.push(mate3Key(selected));mate3White++;renderMate3();
 if(mate3Chess.in_checkmate()){mate3Done=true;mate3Message('🏆 Chính xác! Đã chiếu hết Vua Đen!');accountSaveProgress('mate3_'+MATE3_DATA[mate3Index].num,true,1);return;}
 if(mate3White===3){mate3Done=true;mate3Message('Chưa chiếu hết. Nhấn Làm lại.');return;}
 const options=mate3Options().map(l=>l[mate3History.length]);
 const reply=mate3Chess.moves({verbose:true}).find(m=>options.includes(mate3Key(m)));
 if(!reply){mate3Done=true;mate3Message('Nước Đen trong biến chính không hợp lệ với thế cờ hiện tại. Cần kiểm tra lại vị trí quân và đáp án.');return;}
 mate3Chess.move(reply);mate3History.push(mate3Key(reply));renderMate3();mate3Message('Đen đã đi. Hãy tìm nước tiếp theo!');
}
function clickMate3(sq){
 if(!mate3Chess||mate3Done||mate3Chess.turn()!=='w')return;
 const pc=mate3Chess.get(sq);
 if(!mate3Selected){if(pc&&pc.color==='w'){mate3Selected=sq;renderMate3();}return;}
 if(pc&&pc.color==='w'){mate3Selected=sq;renderMate3();return;}
 const from=mate3Selected;mate3Selected=null;
 const legal=mate3Chess.moves({verbose:true}).filter(m=>m.from===from&&m.to===sq);
 if(!legal.length){mate3Message('Nước đi không hợp lệ.');renderMate3();return;}
 if(legal.some(m=>m.promotion)){renderMate3();showMate3Promotion(from,sq);return;}
 applyMate3Move(from,sq,null);
}
function hintMate3(){if(!mate3Chess||mate3Done)return;if(MATE3_DATA[mate3Index].num===164){const moves=mate3Chess.moves({verbose:true});const remaining=3-mate3White;for(const m of moves){mate3Chess.move(m);const good=mate3Chess.in_checkmate()||mate164CanForce(mate3Chess,remaining-1);mate3Chess.undo();if(good){mate3Message('💡 Gợi ý: Hãy thử quân ở ô '+m.from+'.');return;}}mate3Message('Không tìm thấy nước chiếu hết trong số nước còn lại.');return;}const o=mate3Options();const m=o.length?o[0][mate3History.length]:null;mate3Message(m?'💡 Gợi ý: Hãy thử quân ở ô '+m.slice(0,2)+'.':'Chưa tìm thấy gợi ý phù hợp.');}

