let pvpData=null,pvpSelected=null,pvpSending=false;
function pvpMyColor(){return !pvpData?null:(role==='teacher'?pvpData.teacherColor:(pvpData.teacherColor==='w'?'b':'w'));}
function pvpChess(){if(typeof Chess==='undefined')return null;const c=new Chess();if(pvpData&&pvpData.fen&&!c.load(pvpData.fen))return null;return c;}
function pvpFinished(c){
 if(c.in_checkmate())return '🏆 Chiếu hết! '+(c.turn()==='w'?'Đen':'Trắng')+' thắng.';
 if(c.in_stalemate())return '🤝 Hòa do hết nước đi hợp lệ (pat).';
 if(c.in_threefold_repetition())return '🤝 Hòa do lặp lại thế cờ 3 lần.';
 if(c.insufficient_material())return '🤝 Hòa do không đủ lực lượng.';
 if(c.in_draw())return '🤝 Ván cờ hòa theo luật.';
 return null;
}
function pvpStatus(msg){document.getElementById('pvpStatus').textContent=msg;}
