 if(!pvpData){pvpStatus(!roomRef?'Hãy tạo phòng hoặc vào lớp ở thanh trên trước.':'Chưa bắt đầu ván. Giáo viên chọn Trắng/Đen và nhấn Bắt đầu ván mới.');return;}
 if(pvpData.status==='finished'){pvpStatus(pvpData.result||'Ván đấu đã kết thúc.');return;}
 if(pvpData.drawBy){pvpStatus(pvpData.drawBy===role?'Bạn đã đề nghị hòa; đang chờ đối phương.':'Đối phương đề nghị hòa. Nhấn Đề nghị hòa để chấp nhận, hoặc tiếp tục đi cờ.');return;}
 const turn=chess.turn(),me=pvpMyColor();
